<?php
 namespace Pterodactyl\Services\Dezerx\ServerCreate; use Throwable; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Log; use Illuminate\Database\Eloquent\Collection; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Dezerx\FreeServer; use Pterodactyl\Services\Servers\SuspensionService; use Pterodactyl\Services\Servers\ServerDeletionService; class RenewalRunner { public function __construct( private SuspensionService $suspension, private ServerDeletionService $deletion, ) { } public function backfill(): int { $undated = FreeServer::query()->whereNull('renew_at')->get(); foreach ($undated as $entry) { $entry->forceFill(['renew_at' => ServerCreate::nextDeadline()])->save(); } return $undated->count(); } public function due(): Collection { $cutoff = CarbonImmutable::now()->subHours(ServerCreate::number('grace_hours')); return FreeServer::query() ->with('server') ->whereNull('suspended_at') ->whereNotNull('renew_at') ->where('renew_at', '<=', $cutoff) ->orderBy('renew_at') ->get(); } public function purgeable(): Collection { $days = ServerCreate::number('purge_days'); if ($days < 1) { return new Collection(); } return FreeServer::query() ->with('server') ->whereNotNull('suspended_at') ->where('suspended_at', '<=', CarbonImmutable::now()->subDays($days)) ->orderBy('suspended_at') ->get(); } public function handle(FreeServer $entry): string { $server = $entry->server; if ($server === null) { $entry->delete(); return 'orphaned'; } $action = (string) ServerCreate::setting('expire_action'); Activity::event('server:free.expire') ->subject($server) ->property([ 'action' => $action, 'renew_at' => $entry->renew_at?->toIso8601String(), ]) ->log(); if ($action === ServerCreate::ACTION_DELETE) { $uuid = $server->uuid; $this->deletion->withForce(false)->handle($server); Log::notice('A free server was deleted for not being renewed', ['server' => $uuid]); return 'deleted'; } if (!$server->isSuspended()) { $this->suspension->toggle($server, SuspensionService::ACTION_SUSPEND); } $entry->forceFill(['suspended_at' => CarbonImmutable::now()])->save(); Log::notice('A free server was suspended for not being renewed', ['server' => $server->uuid]); return 'suspended'; } public function purge(FreeServer $entry): string { $server = $entry->server; if ($server === null) { $entry->delete(); return 'orphaned'; } $uuid = $server->uuid; Activity::event('server:free.purge') ->subject($server) ->property(['suspended_at' => $entry->suspended_at?->toIso8601String()]) ->log(); $this->deletion->withForce(false)->handle($server); Log::notice('A suspended free server was removed', ['server' => $uuid]); return 'purged'; } public function fail(FreeServer $entry, Throwable $exception): void { Log::warning('A free server could not be dealt with', [ 'server' => $entry->server?->uuid, 'renew_at' => $entry->renew_at?->toIso8601String(), 'error' => $exception->getMessage(), ]); } } 